export function getCharacterAtlasPlaybackProfileV2135(specializationId, state, direction) {
  const id = String(specializationId || '').trim();
  const st = String(state || 'idle');
  const dir = String(direction || 'south').toLowerCase().replaceAll('_', '-');
  return PROFILES[`${id}/${st}/${dir}`] || null;
}

export function resolveCharacterAtlasProfileFrameV2135(profile, elapsedMs = 0, loop = true) {
  if (!profile || !Array.isArray(profile.frames) || !profile.frames.length) return null;
  const durations = Array.isArray(profile.durations) && profile.durations.length === profile.frames.length ? profile.durations : profile.frames.map(() => 1);
  const totalTicks = durations.reduce((sum, value) => sum + Math.max(1, Number(value) || 1), 0);
  const durationMs = Math.max(1, Number(profile.durationMs) || totalTicks * 1000 / 12);
  const elapsed = Math.max(0, Number(elapsedMs) || 0);
  const t = loop ? elapsed % durationMs : Math.min(elapsed, durationMs - 0.001);
  let tick = t / durationMs * totalTicks;
  for (let i = 0; i < profile.frames.length; i++) {
    const span = Math.max(1, Number(durations[i]) || 1);
    if (tick < span) return profile.frames[i];
    tick -= span;
  }
  return profile.frames[profile.frames.length - 1];
}

export function auditCharacterAtlasPlaybackV2135() {
  const entries = Object.entries(PROFILES);
  const errors = [];
  for (const [key, p] of entries) {
    if (!p.frames.length || p.frames.length !== p.durations.length) errors.push(`invalid_keyframes:${key}`);
    if (p.frames.some((v) => !Number.isInteger(v) || v < 0 || v > 7)) errors.push(`invalid_frame_index:${key}`);
    if (p.durations.some((v) => !Number.isInteger(v) || v < 1)) errors.push(`invalid_frame_duration:${key}`);
    if (!(p.durationMs > 0)) errors.push(`invalid_duration:${key}`);
  }
  return Object.freeze({ profileCount: entries.length, periodicCycleCount: entries.filter(([,p]) => p.kind === 'periodic_cycle').length, heldKeyframeCount: entries.filter(([,p]) => p.kind === 'held_keyframes').length, valid: errors.length === 0, errors: Object.freeze(errors) });
}
